-- Correcao do parser de Extrato Banco de Horas (competencia 2026-06)
-- Gerado por _gerar_sql_so_banco.py


on conflict (id_rh, competencia) do update set
  setor = excluded.setor, horas_credito = excluded.horas_credito, horas_debito = excluded.horas_debito, saldo_mes = excluded.saldo_mes, saldo_acumulado = excluded.saldo_acumulado, valor_total = excluded.valor_total, origem = excluded.origem, observacao = excluded.observacao;


on conflict (competencia, setor) do update set
  qtd_colaboradores = excluded.qtd_colaboradores, horas_saldo_total = excluded.horas_saldo_total, valor_total = excluded.valor_total, origem = excluded.origem, observacao = excluded.observacao;
